/* ============================================================
   76° — Seventy Six Degrees · tokens.css
   The ONLY file in the system permitted to contain color literals.
   (Slop Firewall A1: any hex/rgb/hsl outside this file is a defect.)
   ============================================================ */

@layer sv-tokens {
  :root {
    /* neutrals — the wall & the ink */
    --sv-band:       #1B1F26;   /* ink band (header) */
    --sv-band-line:  #2C323B;   /* hairlines on band */
    --sv-band-soft:  #8A93A2;   /* soft text on band */
    --sv-wall:       #F2F3F5;   /* platinum background */
    --sv-paper:      #FFFFFF;   /* card surface — and ONLY that */
    --sv-on-dark:    #FFFFFF;   /* the mark on dark chrome or on a seed fill:
                                   band text, on-band focus ring, primary
                                   button label, checkbox/radio mark. Never
                                   overridden per mode — the band and the seed
                                   do not invert, so neither does their mark. */
    --sv-ink:        #1C2026;   /* primary text */
    --sv-ink-soft:   #667080;   /* secondary text */
    --sv-ink-faint:  #99A1AD;   /* labels, hints — never sole carrier (C2) */
    --sv-line:       #E9EBEE;   /* internal hairlines */
    --sv-field-line: #D8DCE1;   /* form field borders */
    --sv-field-line-strong: #7E8794; /* 3.63:1 on paper. For controls whose
                                   BORDER is the ONLY affordance — an empty
                                   PinField box carries no label, no value and
                                   no fill, so the hairline above would leave
                                   it at 1.38:1 and fail the 3:1 non-text bar
                                   (WCAG 1.4.11). Ordinary fields keep the
                                   hairline: their label and value identify
                                   them, the border only decorates. */
    --sv-compare:    #D6DAE0;   /* comparison series in charts — the only
                                   permitted non-token chart color, aliased */

    /* seed — Layer 3, per product (default: Cobalt / ERP) */
    --sv-seed:       #2C5BE0;
    --sv-seed-text:  #2C5BE0;   /* seed used AS text; differs when fills pass
                                   but text fails the C1 rule (see Signal) */
    --sv-seed-line:  var(--sv-seed); /* seed used AS a 1–2px LINE: focus rings,
                                   focus borders, accent rules. Splits from the
                                   fill for exactly the reason --sv-seed-text
                                   does — on dark paper the raw seed is 2.90:1
                                   and misses the 3:1 non-text bar, so a focus
                                   ring drawn in it is invisible. Tracks the
                                   seed in light; tracks --sv-seed-text in
                                   dark, where that step is already AA-verified. */
    --sv-seed-deep:  #1E44B4;   /* pressed */
    --sv-seed-tint:  #EEF3FE;   /* icon tiles, selected rows */

    /* functional — words and 6px dots ONLY (contrast-verified on paper) */
    --sv-ok:         #14804A;   /* 4.98:1 on white — AA */
    --sv-bad:        #C43D2E;   /* 5.18:1 on white — AA */
    --sv-on-bad:     #FFFFFF;   /* the mark on a --sv-bad FILL (the dialog's
                                   final confirm — the one red fill allowed).
                                   Unlike --sv-on-dark this DOES flip per mode,
                                   because --sv-bad itself brightens on dark. */

    /* scrim — Dialog only, flat, no blur */
    --sv-scrim:      rgba(27, 31, 38, 0.4);

    /* geometry & elevation */
    --sv-r:          4px;                              /* the only radius */
    --sv-shadow:     0 1px 2px rgba(16, 20, 28, 0.05); /* the only shadow */

    /* spacing scale (4px base) */
    --sv-s1: 4px;  --sv-s2: 8px;  --sv-s3: 12px; --sv-s4: 16px;
    --sv-s5: 20px; --sv-s6: 24px; --sv-s7: 32px; --sv-s8: 40px;

    /* type */
    --sv-font-ui:   'Hanken Grotesk Variable', 'Hanken Grotesk', system-ui, sans-serif;
    --sv-font-mono: 'Fragment Mono', ui-monospace, monospace;

    /* motion — opacity/color fades only, never layout (A1).
       Both collapse to 0ms under prefers-reduced-motion. */
    --sv-t-fast: 120ms;
    --sv-t:      160ms;

    /* layering — the only z-index ladder (Firewall E). Non-visual.
       Native <dialog> and [popover] use the browser top layer and
       need no z-index at all — prefer them. */
    --sv-z-band:   10;   /* sticky band / topbar */
    --sv-z-sticky: 20;   /* sticky in-page (table headers) */
    --sv-z-scrim:  30;   /* dialog scrim (non-native fallback) */
    --sv-z-dialog: 40;   /* dialog (non-native fallback) */
    --sv-z-toast:  50;   /* toasts */
    --sv-z-tip:    60;   /* tooltips (non-popover fallback) */
    --sv-z-skip:   70;   /* skip link (C4) — first tab stop, wins over all */
  }

  @media (prefers-reduced-motion: reduce) {
    :root {
      --sv-t-fast: 0ms;
      --sv-t:      0ms;
    }
  }

  /* ---- Per-product seed registry (Layer 3) ------------------
     One seed per product. tint = seed at ~8% on white,
     deep = seed darkened ~20%. New seeds must pass C1:
     seed-on-white >= 4.5:1 AND white-on-seed >= 4.5:1. */

  [data-seed='cobalt'] {
    --sv-seed:      #2C5BE0;   /* ERP · 5.70:1 both ways */
    --sv-seed-text: #2C5BE0;
    --sv-seed-line: var(--sv-seed);  /* 5.71:1 on paper */
    --sv-seed-deep: #1E44B4;
    --sv-seed-tint: #EEF3FE;
  }

  [data-seed='verdigris'] {
    --sv-seed:      #12836F;   /* CRM · 5.0:1 both ways */
    --sv-seed-text: #12836F;
    --sv-seed-line: var(--sv-seed);  /* 4.66:1 on paper */
    --sv-seed-deep: #0D6152;
    --sv-seed-tint: #EAF5F2;
  }

  [data-seed='signal'] {
    --sv-seed:      #D9531E;   /* POS · fills only (white on seed 4.6:1) */
    --sv-seed-text: #C24413;   /* seed-as-text variant — passes on white */
    --sv-seed-line: var(--sv-seed);  /* 4.03:1 on paper */
    --sv-seed-deep: #A83E12;
    --sv-seed-tint: #FCF0EA;
  }
}

/* ============================================================
   Dark mode — the disciplined dark surface (v0.2.0).
   Light stays the default (light-first). Dark is opt-in via
   <html data-mode="dark"> and changes ONLY these tokens:
   the same paper-on-a-wall physics, inverted. Cards stay the
   lightest surface in view; the band stays the darkest.
   Functional + seed-as-text steps are re-verified AA on dark
   paper (#1B1F26). Nothing else may change per mode.
   ============================================================ */

@layer sv-tokens {
  :root {
    color-scheme: light;
  }

  [data-mode='dark'] {
    color-scheme: dark;

    /* neutrals — inverted ladder, paper is the LIGHTEST surface */
    --sv-band:       #0D1014;   /* chrome stays the darkest thing on screen */
    --sv-band-line:  #232932;
    --sv-band-soft:  #8A93A2;
    --sv-wall:       #121519;   /* the wall recedes */
    --sv-paper:      #1B1F26;   /* cards read as raised paper */
    --sv-ink:        #E6E9EE;   /* 13.9:1 on dark paper */
    --sv-ink-soft:   #A7AFBB;   /* 7.4:1 on dark paper — AA */
    --sv-ink-faint:  #6E7784;   /* never a sole carrier (C2), same as light */
    --sv-line:       #272D36;
    --sv-field-line: #3A414C;
    --sv-field-line-strong: #6E7784; /* 3.65:1 on dark paper */
    --sv-compare:    #3C434E;   /* comparison series on dark grids */

    /* functional — brightened to hold AA on dark paper */
    --sv-ok:         #4CC38A;   /* ≥ 4.5:1 on #1B1F26 */
    --sv-bad:        #F0705F;   /* ≥ 4.5:1 on #1B1F26 */
    --sv-on-bad:     #1B1F26;   /* 5.66:1 on the brightened fill (white is
                                   2.92:1 there). --sv-on-dark stays white. */

    /* seed-as-surface is unchanged (white-on-seed already passed C1);
       seed-as-text brightens per seed below; tint derives from the seed
       so every registered seed gets a correct dark tint for free. */
    --sv-seed-tint:  color-mix(in srgb, var(--sv-seed) 16%, var(--sv-paper));

    --sv-scrim:      rgba(0, 0, 0, 0.55);
    --sv-shadow:     0 1px 2px rgba(0, 0, 0, 0.4);
  }

  /* seed-as-LINE follows seed-as-text on dark: the raw seed is 2.90:1 on
     dark paper, so every focus ring drawn in it would fail 1.4.11/2.4.11.
     These steps are already AA as text, so they clear 3:1 as a line with
     room to spare (cobalt 6.16:1, verdigris 7.19:1, signal 7.65:1). */

  [data-mode='dark'][data-seed='cobalt'],
  [data-mode='dark']:not([data-seed]) {
    --sv-seed-text: #7C9BF2;    /* cobalt as text on dark paper — AA */
    --sv-seed-line: var(--sv-seed-text);
  }

  [data-mode='dark'][data-seed='verdigris'] {
    --sv-seed-text: #35BFA4;
    --sv-seed-line: var(--sv-seed-text);
  }

  [data-mode='dark'][data-seed='signal'] {
    --sv-seed-text: #F59A6B;
    --sv-seed-line: var(--sv-seed-text);
  }
}

/* ============================================================
   76° · base.css — reset, typography defaults, focus contract
   ============================================================ */

@layer sv-base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    margin: 0;
    background: var(--sv-wall);
    color: var(--sv-ink);
    font-family: var(--sv-font-ui);
    font-size: 13px;
    line-height: 1.5;
    font-weight: 500;
    -webkit-font-smoothing: antialiased;
  }

  h1, h2, h3, h4, p, figure, blockquote, dl, dd {
    margin: 0;
  }

  img, svg {
    display: block;
    max-width: 100%;
  }

  button, input, select, textarea {
    font: inherit;
    color: inherit;
  }

  /* C3 · Focus — every interactive element, no exceptions */
  :focus-visible {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  /* On the band, focus is white for contrast — in both modes */
  .sv-band :focus-visible {
    outline-color: var(--sv-on-dark);
  }

  /* A4 · numbers that can change are tabular, always */
  .sv-num {
    font-variant-numeric: tabular-nums;
  }

  /* Mono metadata voice (Law 4) */
  .sv-mono {
    font-family: var(--sv-font-mono);
    font-size: 10px;
    font-weight: 400;
    letter-spacing: 0.13em;
    text-transform: uppercase;
  }

  /* C4 · Skip link — first tab stop, visible on focus over the band */
  .sv-skip {
    position: absolute;
    left: var(--sv-s4);
    top: var(--sv-s2);
    z-index: var(--sv-z-skip);
    padding: var(--sv-s2) var(--sv-s4);
    background: var(--sv-paper);
    color: var(--sv-ink);
    border-radius: var(--sv-r);
    box-shadow: var(--sv-shadow);
    font-size: 12px;
    font-weight: 600;
    text-decoration: none;
    transform: translateY(-200%);
  }

  .sv-skip:focus-visible {
    transform: none;
  }

  /* Visually hidden, screen-reader available */
  .sv-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* C7 · reduced motion — handled at the token layer: every transition
     in the system uses var(--sv-t) / var(--sv-t-fast), which collapse
     to 0ms under prefers-reduced-motion (see tokens.css). 76° loses
     nothing, by design. */
}

/** Minimal class combiner. No dependency needed. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ');
}
